custom_css:
/* 墨序 Moxu 1.0.2 · SillyTavern · system fonts, no external assets.
   Core layout only. No universal descendant resets, iframe rewrites or chat containment.
   Native theme flags also enable Fast UI / No Shadows / Reduced Motion. */
:root {
  --mx-bg: #111415;
  --mx-panel: #191d1f;
  --mx-field: #22282a;
  --mx-line: #343d40;
  --mx-text: #e4e9e7;
  --mx-muted: #abb8b3;
  --mx-accent: #a8c8b5;
  --mx-user: #17201e;
  --mx-radius: 8px;
  --mainFontFamily: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", "Noto Sans TC", "Microsoft JhengHei", sans-serif;
  --monoFontFamily: ui-monospace, "SFMono-Regular", Consolas, monospace;
  --interactable-outline-color: var(--mx-accent);
  --interactable-outline-color-faint: var(--mx-accent);
}
body {
  background-color: var(--mx-bg);
  color: var(--mx-text);
}
/* A flat canvas replaces background artwork while this theme is active. */
#bg1, #bg_custom {
  background-image: none !important;
  background-color: var(--mx-bg) !important;
  filter: none !important;
}
#top-bar, #chat, #send_form,
.drawer-content, .popup, #options, #extensionsMenu {
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: none !important;
  text-shadow: none !important;
}
#top-bar {
  background: var(--mx-panel);
  border-bottom: 1px solid var(--mx-line);
}
#top-settings-holder .drawer-icon {
  color: var(--mx-muted);
  text-shadow: none;
  filter: none;
}
#top-settings-holder .drawer-icon.openIcon {
  color: var(--mx-accent);
  opacity: 1;
}
#top-settings-holder .drawer-icon.closedIcon { opacity: .8; }
#sheld {
  border-left: 1px solid var(--mx-line);
  border-right: 1px solid var(--mx-line);
}
#chat {
  background: var(--mx-bg);
  scroll-behavior: auto;
  scrollbar-width: thin;
  scrollbar-color: var(--mx-line) var(--mx-bg);
}
#chat > .mes {
  padding: 22px 20px 16px;
  margin: 0;
  border-radius: 0;
  border-bottom: 1px solid var(--mx-line);
  box-shadow: none;
  text-shadow: none;
}
#chat > .mes[is_user="true"]:not(.selected) {
  background-color: var(--mx-user);
}
#chat > .mes[is_user="false"]:not(.selected) {
  background-color: var(--mx-bg);
}
#chat > .mes > .mes_block { min-width: 0; }
#chat > .mes > .mes_block > .ch_name {
  color: var(--mx-text);
  letter-spacing: .025em;
  margin-bottom: 5px;
}
#chat > .mes > .mes_block > .mes_text {
  line-height: 1.8;
  font-weight: 400;
  overflow-wrap: anywhere;
}
#chat > .mes > .mes_block > .mes_text > p { margin-bottom: .8em; }
#chat > .mes > .mes_block > .mes_text > p:last-child { margin-bottom: 0; }
#chat > .mes > .mes_block > .mes_text > blockquote {
  border-left: 2px solid var(--mx-accent);
  margin: 12px 0;
  padding: 3px 14px;
  color: var(--mx-muted);
  background: transparent;
}
#chat > .mes > .mes_block > .mes_text > pre {
  max-width: 100%;
  overflow-x: auto;
  border: 1px solid var(--mx-line);
  border-radius: var(--mx-radius);
  background-color: var(--mx-panel);
}
/* HTML source visibility is managed by the optional Moxu Source Guard extension. */
#chat > .mes > .mes_block > .mes_text > table {
  display: block;
  overflow-x: auto;
  max-width: 100%;
}
#chat > .mes > .mes_block > .mes_text > hr {
  height: 1px;
  background: var(--mx-line);
  opacity: 1;
}
#chat > .mes > .mes_block > .mes_text > details {
  border: 1px solid var(--mx-line);
  border-radius: var(--mx-radius);
  padding: 10px 12px;
  margin: 10px 0;
}
#chat > .mes > .mes_block > .mes_text > details > summary {
  cursor: pointer;
  color: var(--mx-accent);
  min-height: 28px;
}
#chat > .mes .mes_buttons {
  opacity: 1;
  filter: none;
  gap: 4px;
}
#chat > .mes .mes_buttons .mes_button {
  opacity: .8;
  filter: none;
  border-radius: 6px;
  padding: 6px;
}
#chat > .mes > .mesAvatarWrapper > .avatar,
#chat > .mes > .avatar {
  box-shadow: none;
  border-radius: var(--mx-radius);
}
.drawer-content, .popup {
  background-color: var(--mx-panel);
  border: 1px solid var(--mx-line);
  border-radius: var(--mx-radius);
}
.drawer-content .inline-drawer-header {
  background-image: none;
  border-radius: 6px;
}
.drawer-content .text_pole,
.drawer-content textarea,
.drawer-content select,
.popup .text_pole,
.popup textarea,
.popup select {
  background-color: var(--mx-field);
  border-color: var(--mx-line);
  border-radius: 6px;
}
.drawer-content .menu_button, .popup .menu_button {
  box-shadow: none;
  text-shadow: none;
  border-radius: 6px;
}
#form_sheld { margin-top: 0; }
#send_form {
  background-color: var(--mx-panel);
  border: 0;
  border-top: 1px solid var(--mx-line);
  border-radius: 0;
  padding: 6px 8px;
  padding-bottom: max(6px, env(safe-area-inset-bottom, 0px));
}
#send_form:focus-within { border-top-color: var(--mx-accent); }
#send_textarea {
  min-width: 0;
  font-size: max(16px, var(--mainFontSize));
  line-height: 1.6;
  padding-left: 8px;
  padding-right: 8px;
  color: var(--mx-text);
  caret-color: var(--mx-accent);
  text-shadow: none;
}
#send_textarea::placeholder { color: var(--mx-muted); opacity: 1; }
#send_but {
  color: var(--mx-accent);
  border-radius: var(--mx-radius);
  text-shadow: none;
}
/* Do not change display, visibility or positioning of Send/Stop/menu controls. */
#send_but:focus-visible, #options_button:focus-visible,
.drawer-icon:focus-visible, .mes_button:focus-visible,
.drawer-content .menu_button:focus-visible, .popup .menu_button:focus-visible {
  outline: 2px solid var(--mx-accent);
  outline-offset: 2px;
}
@media (hover: hover) {
  #top-settings-holder .drawer-icon:hover,
  #chat > .mes .mes_buttons .mes_button:hover { color: var(--mx-accent); }
  #send_but:hover { background-color: var(--mx-field); }
}
@media (max-width: 1000px) {
  #sheld { border-left: 0; border-right: 0; }
  #chat > .mes {
    padding: 17px 12px 13px;
    --avatar-base-height: 36px;
    --avatar-base-width: 36px;
  }
  #chat > .mes > .mes_block { padding-left: 10px; }
  #chat > .mes .mes_buttons { opacity: 1; }
  #send_form { padding-left: 5px; padding-right: 5px; }
}
@media (pointer: coarse) {
  #form_sheld:not(.isExecutingCommandsFromChatInput) #leftSendForm > .interactable,
  #form_sheld:not(.isExecutingCommandsFromChatInput) #rightSendForm > .interactable {
    min-width: 40px;
    min-height: 40px;
  }
}
